WITH with_gaps AS (SELECT *, CASE WHEN txn_time - LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time, id) > INTERVAL 60 DAYS THEN 1 ELSE 0 END AS is_new_session FROM transactions), sessionized AS (SELECT id, account_id, amount, txn_time, merchant, SUM(is_new_session) OVER (PARTITION BY account_id ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM with_gaps) SELECT s.id, s.account_id, s.amount, s.txn_time, s.merchant, s.burst_id, CASE WHEN merchant RLIKE '^(7-Eleven|Amazon)$' THEN 'GROUP_B' WHEN merchant RLIKE '^(Grab|Lazada)$' THEN 'EXTENDED' ELSE 'PRIORITY' END AS merchant_zone, (SELECT MAX(x.amount) FROM transactions x WHERE x.account_id = s.account_id) AS max_transaction_amount FROM sessionized s
